ROOT = Path(__file__).resolve().parents[3]
PROV = Path(__file__).resolve().parent
OUT = ROOT/'results/cost_sources_v6_candidates_v1'
SOURCES = {}


def read(path, expected=None):
    p = Path(path)
    p = p if p.is_absolute() else ROOT/p
    p = p.resolve()
    assert p.suffix in {'.json','.py','.log'} and p.stat().st_size < 30_000_000
    raw = p.read_bytes()
    sha = hashlib.sha256(raw).hexdigest()
    if expected:
        assert sha == expected, (p, sha, expected)
    source = dict(path=str(p),sha256=sha,bytes=len(raw))
    if str(p) in SOURCES:
        assert SOURCES[str(p)] == source, ('changed source',p)
    SOURCES[str(p)] = source
    dest = PROV/'inputs'/(sha+'_'+p.name)
    if not dest.exists():
        dest.write_bytes(raw)
    return json.loads(raw) if p.suffix == '.json' else raw, source


def pointer(data, path):
    for k in path.strip('/').split('/'):
        data = data[int(k)] if isinstance(data,list) else data[k]
    return data


